    @DeleteMapping("/timetable/clear")
    fun clear(): ResponseEntity<ApiResponse<String>> {
        val count = matrixService.clearTimetable()
        return ResponseEntity.ok(ApiResponse.success("OK", "$count ta dars tozalandi"))
